  ["593d65b735ec1b67"] = { "È uno scherzo?", "." },
  ["594aa2bbf005a868"] = { "Fuoco di soppressione tattico, Vipore. Non risparmiarti.", "." },
  ["594b311e4b7a77e1"] = { "Debole {class}! Non sei all'altezza della tribù Scheggiadura!", "." },
