  ["594dee2b726b9d12"] = { "Per amore di tutto ciò che è santo e caro, dimmi che sei qui per liberarci da questa terra maledetta. Anche se lavoro per la Marshal Expeditions, ti darei i denti d'oro che ho in bocca pur di infilarmi nel tuo zaino e andarmene da qui.", "." },
  ["595352a77b064e3d"] = { "Guarda chi si vede. Cosa ti porto, {name}?", "." },
