  ["596bb1a26dea2225"] = { "%s ringhia in segno d'intesa, poi si raddrizza e si allontana nella foresta.", "." },
  ["597a1671045ed8ca"] = { "%s annusa l'aria...", "." },
  ["59810b7792a2dc46"] = { "Studi le scienze mediche?", "." },
