  ["598ab44a6e827f9b"] = { "La Frostwolf Relief Hut è stata presa dall'⟦Horde=Orda⟧!", "." },
  ["599379901fa08888"] = { "Ringrazio la Luce per questa benedizione. Che sia usata per la giustizia e per difendere tutte le creature buone.", "." },
