  ["59c6fe82171f4200"] = { "Se desideri davvero imparare questa professione, ti indirizzerei verso Ainethil, un'abile alchimista della ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nella parte settentrionale di Darnassus.", "." },
  ["59cbd1386b954a15"] = { "Sono passati molti anni...", "." },
