  ["59f51cd271fe25c2"] = { "Il ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧ è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo conquisterà!", "." },
